pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0 && amount <= 100 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        uint256 balanceBefore = actor.balance;
        vm.prank(actor);
        try c.withdraw(amount) {
            uint256 balanceAfter = actor.balance;
            assertTrue(balanceAfter == balanceBefore + amount);
        } catch { }
    }
}
